using System.Globalization;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;using Servicio.RetazoMarket.Business.DTOs.Pedido;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class PedidoService:IPedidoService {private const decimal TasaIva=0m;private const int CantidadMinimaSabanaPersonalizada=3;private readonly IPedidoDataService _consultas;private readonly IPedidoAdministracionDataService _administracion;private readonly IClienteDataService _clientes;private readonly IMetodoPagoDataService _metodos;private readonly IProductoDataService _productos;private readonly IDescuentoDataService _descuentos;public PedidoService(IPedidoDataService consultas,IPedidoAdministracionDataService administracion,IClienteDataService clientes,IMetodoPagoDataService metodos,IProductoDataService productos,IDescuentoDataService descuentos)=>(_consultas,_administracion,_clientes,_metodos,_productos,_descuentos)=(consultas,administracion,clientes,metodos,productos,descuentos);public async Task<IReadOnlyList<PedidoResponse>> ObtenerTodosAsync(CancellationToken ct=default)=>(await _consultas.ObtenerTodosAsync(ct)).Select(PedidoBusinessMapper.ToResponse).ToList();public async Task<PedidoResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _consultas.ObtenerPorIdAsync(id,ct);return m is null?null:PedidoBusinessMapper.ToResponse(m);}public async Task<DataPagedResult<PedidoResponse>> BuscarAsync(PedidoFiltroRequest f,CancellationToken ct=default){var e=PedidoValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _consultas.BuscarAsync(new PedidoFiltroDataModel{id_cliente=f.id_cliente,estado=f.estado?.Trim().ToUpperInvariant(),fecha_desde_utc=f.fecha_desde_utc,fecha_hasta_utc=f.fecha_hasta_utc,id_linea=f.id_linea,id_metodo=f.id_metodo,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(PedidoBusinessMapper.ToResponse).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<PedidoResponse> CrearAsync(CrearPedidoRequest r,CancellationToken ct=default){var e=PedidoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ValidarCabecera(r.id_cliente,r.id_metodo,ct);var model=await ConstruirPedido(r.id_cliente,r.id_metodo,r.entrega_fisica,r.detalles,DateTime.UtcNow,ct);try{return PedidoBusinessMapper.ToResponse(await _administracion.CrearAsync(model,ct));}catch(InvalidOperationException ex){throw new ValidationException(ex.Message);}}public async Task<PedidoResponse?> ActualizarAsync(ActualizarPedidoRequest r,CancellationToken ct=default){var e=PedidoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);var actual=await _consultas.ObtenerPorIdAsync(r.id_pedido,ct);if(actual is null)return null;if(actual.estado!="PEN")throw new ValidationException("Solo se pueden editar pedidos pendientes.");await ValidarCabecera(r.id_cliente,r.id_metodo,ct);var model=await ConstruirPedido(r.id_cliente,r.id_metodo,r.entrega_fisica,r.detalles,actual.fecha_hora,ct);model.id_pedido=r.id_pedido;return (await _administracion.ActualizarPendienteAsync(model,ct)) is { } actualizado?PedidoBusinessMapper.ToResponse(actualizado):null;}private async Task ValidarCabecera(int clienteId,int metodoId,CancellationToken ct){var c=await _clientes.ObtenerPorIdAsync(clienteId,ct);if(c is null||c.cli_estado!="ACT")throw new ValidationException("El cliente no existe o está inactivo.");if(await _metodos.ObtenerPorIdAsync(metodoId,ct) is null)throw new ValidationException("El método de pago no existe.");}private async Task<PedidoDataModel> ConstruirPedido(int cliente,int metodo,string entrega,IReadOnlyCollection<DetallePedidoRequest> solicitudes,DateTime fecha,CancellationToken ct){var detalles=new List<ProductoPedidoDataModel>();foreach(var solicitud in solicitudes){var producto=await _productos.ObtenerPorIdAsync(solicitud.id_producto,ct)??throw new ValidationException($"El producto {solicitud.id_producto} no existe.");if(producto.prod_estado!="ACT")throw new ValidationException($"El producto {producto.prod_nombre} está inactivo.");if(producto.stock_actual<solicitud.cantidad)throw new ValidationException($"Stock insuficiente para {producto.prod_nombre}.");var personalizacion=await ValidarPersonalizacion(producto,solicitud,ct);var precio=Redondear(producto.precio_base+personalizacion.CostoUnitario);var baseItem=Redondear(precio*solicitud.cantidad);var regla=await _descuentos.ObtenerAplicableAsync(producto.id_producto,solicitud.cantidad,ct);var porcentaje=regla?.porcentaje??0m;var monto=Redondear(baseItem*porcentaje/100m);var subtotal=Redondear(baseItem-monto);detalles.Add(new(){id_producto=producto.id_producto,cantidad=solicitud.cantidad,precio_unitario=precio,porcentaje_descuento=porcentaje,monto_descuento=monto,subtotal_item=subtotal,personalizacion_selec=personalizacion.Historico});}var subtotalPedido=Redondear(detalles.Sum(x=>x.subtotal_item));var iva=Redondear(subtotalPedido*TasaIva/100m);return new(){id_metodo=metodo,id_cliente=cliente,fecha_hora=fecha,estado="PEN",entrega_fisica=entrega.Trim().ToUpperInvariant(),subtotal=subtotalPedido,iva=iva,total=Redondear(subtotalPedido+iva),fecha_pago=null,Detalles=detalles};}private async Task<(JsonElement Historico,decimal CostoUnitario)> ValidarPersonalizacion(ProductoDataModel producto,DetallePedidoRequest solicitud,CancellationToken ct){if(solicitud.personalizaciones.Count>0&&producto.es_personalizable!="S")throw new ValidationException($"El producto {producto.prod_nombre} no admite personalización.");var configuraciones=producto.Personalizaciones;var seleccionadas=solicitud.personalizaciones.ToDictionary(x=>x.id_opcion);var faltantes=configuraciones.Where(x=>x.valores_json.TryGetProperty("requerido",out var req)&&req.ValueKind==JsonValueKind.True&&!seleccionadas.ContainsKey(x.id_opcion)).ToList();if(faltantes.Count>0)throw new ValidationException($"Faltan personalizaciones requeridas para {producto.prod_nombre}.");if(seleccionadas.Count>0&&EsSabana(producto)&&solicitud.cantidad<CantidadMinimaSabanaPersonalizada)throw new ValidationException($"Las sábanas personalizadas requieren mínimo {CantidadMinimaSabanaPersonalizada} unidades.");var atributos=new List<object>();decimal costoTotal=0;foreach(var seleccion in solicitud.personalizaciones){var config=configuraciones.FirstOrDefault(x=>x.id_opcion==seleccion.id_opcion)??throw new ValidationException("La personalización seleccionada no pertenece al producto.");var (valor,costoOpcion)=ValidarValor(config,seleccion.valor);var costo=Redondear(config.costo_adicional+costoOpcion);costoTotal+=costo;atributos.Add(new{id_opcion=config.id_opcion,nombre_atr=config.nombre_atr,tipo_valor=config.tipo_valor,valor,costo_adicional=costo});}return(JsonSerializer.SerializeToElement(new{version=1,atributos}),Redondear(costoTotal));}private static (JsonElement,decimal) ValidarValor(PersonalizacionResumenDataModel c,JsonElement valor){var j=c.valores_json;return c.tipo_valor switch{"LISTA" or "COLOR"=>ValidarOpcionCodigo(j,valor),"MATERIAL"=>ValidarMaterial(j,valor),"TEXTO"=>ValidarTexto(j,valor),"MEDIDA"=>ValidarMedida(j,valor),_=>throw new ValidationException("Tipo de personalización no soportado.")};}private static (JsonElement,decimal) ValidarOpcionCodigo(JsonElement j,JsonElement v){var codigo=v.ValueKind==JsonValueKind.String?v.GetString():v.ValueKind==JsonValueKind.Object&&v.TryGetProperty("codigo",out var c)?c.GetString():null;var opcion=j.GetProperty("opciones").EnumerateArray().FirstOrDefault(x=>string.Equals(x.GetProperty("codigo").GetString(),codigo,StringComparison.OrdinalIgnoreCase));if(opcion.ValueKind==JsonValueKind.Undefined)throw new ValidationException("La opción seleccionada no está permitida.");var normal=JsonSerializer.SerializeToElement(new{codigo=opcion.GetProperty("codigo").GetString(),nombre=opcion.GetProperty("nombre").GetString()});return(normal,CostoOpcion(opcion));}private static (JsonElement,decimal) ValidarMaterial(JsonElement j,JsonElement v){var id=v.ValueKind==JsonValueKind.Number?v.GetInt32():v.ValueKind==JsonValueKind.Object&&v.TryGetProperty("id_material",out var x)?x.GetInt32():0;var opcion=j.GetProperty("opciones").EnumerateArray().FirstOrDefault(o=>o.GetProperty("id_material").GetInt32()==id);if(opcion.ValueKind==JsonValueKind.Undefined)throw new ValidationException("El material seleccionado no está permitido.");var normal=JsonSerializer.SerializeToElement(new{id_material=id,nombre=opcion.GetProperty("nombre").GetString()});return(normal,CostoOpcion(opcion));}private static (JsonElement,decimal) ValidarTexto(JsonElement j,JsonElement v){if(v.ValueKind!=JsonValueKind.String)throw new ValidationException("El valor de TEXTO debe ser una cadena.");var texto=v.GetString()??string.Empty;var min=j.GetProperty("longitud_minima").GetInt32();var max=j.GetProperty("longitud_maxima").GetInt32();if(texto.Length<min||texto.Length>max)throw new ValidationException("El texto no cumple la longitud configurada.");if(j.TryGetProperty("patron",out var p)&&!string.IsNullOrWhiteSpace(p.GetString())&&!Regex.IsMatch(texto,p.GetString()!))throw new ValidationException("El texto no cumple el patrón configurado.");return(JsonSerializer.SerializeToElement(texto),0m);}private static (JsonElement,decimal) ValidarMedida(JsonElement j,JsonElement v){decimal valor;if(v.ValueKind==JsonValueKind.Number)valor=v.GetDecimal();else if(v.ValueKind==JsonValueKind.Object&&v.TryGetProperty("valor",out var x)&&x.TryGetDecimal(out var n))valor=n;else throw new ValidationException("La medida debe ser numérica.");var min=j.GetProperty("minimo").GetDecimal();var max=j.GetProperty("maximo").GetDecimal();if(valor<min||valor>max)throw new ValidationException("La medida está fuera del rango permitido.");return(JsonSerializer.SerializeToElement(new{valor,unidad=j.GetProperty("unidad").GetString()}),0m);}private static decimal CostoOpcion(JsonElement opcion)=>opcion.TryGetProperty("costo_adicional",out var c)?c.GetDecimal():0m;private static decimal Redondear(decimal x)=>decimal.Round(x,2,MidpointRounding.AwayFromZero);private static bool EsSabana(ProductoDataModel p){var texto=(p.Linea?.lin_nombre??string.Empty).Normalize(NormalizationForm.FormD);var limpio=new string(texto.Where(c=>CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark).ToArray()).ToUpperInvariant();return limpio.Contains("SABANA");}public async Task<PagoSimuladoResponse> PagarAsync(int id,CancellationToken ct=default){if(id<=0)throw new ValidationException("El id del pedido es inválido.");var r=await _consultas.PagarAsync(id,ct);return r.Estado switch{EstadoPagoSimuladoData.Exitoso=>new(){id_pedido=id,estado="REA",fecha_pago_utc=r.fecha_pago_utc!.Value},EstadoPagoSimuladoData.PedidoNoEncontrado=>throw new NotFoundException("El pedido no existe."),EstadoPagoSimuladoData.PedidoNoPendiente=>throw new BusinessException("El pedido ya fue pagado o no está pendiente."),EstadoPagoSimuladoData.PedidoSinDetalles=>throw new ValidationException("El pedido no contiene detalles."),EstadoPagoSimuladoData.StockInsuficiente=>throw new BusinessException("No existe stock suficiente para completar el pago: "+string.Join(", ",r.ProductosSinStock.Select(x=>$"producto {x.id_producto} ({x.stock_disponible}/{x.cantidad_requerida})"))),EstadoPagoSimuladoData.ConflictoConcurrencia=>throw new BusinessException("El stock cambió durante el pago; vuelva a intentarlo."),_=>throw new BusinessException("No fue posible completar el pago simulado.")};}}
